def reward(r):
    st = r.stages or {}
    green_off = bool(st.get("unstack the green off the red"))
    aligned = bool(st.get("align the red over the green"))
    if r.task_completed:
        return 1.0
    base = (r.reward or 0.0)
    s = base
    if green_off:
        s = max(s, 0.40)
    if green_off and aligned:
        s = max(s, 0.55)
    if aligned:
        s = max(s, 0.42)
    return min(0.99, s)
